                    return int(v[a]), int(v[b])
            for k in ("pos", "position", "loc", "location"):
                p = pos(v.get(k))
                if p is not None:
                    return p
        return None

    s = None
    for k in ("self_position", "self", "me", "player", "unit", "pos", "position"):
        s = pos(o.get(k))
        if s is not None:
            break
    if s is None:
        return [0, 0]

    op = None
    for k in ("opponent_position", "opponent", "enemy", "other"):
        op = pos(o.get(k))
        if op is not None:
            break

    res = o.get("resources") or []
    obs = o.get("obstacles") or []
    sx, sy = s

    best = None
    best_d = 10**9
    for r in res:
        p = pos(r)
        if p is None:
            continue
        d = abs(p[0] - sx) + abs(p[1] - sy)
        if d < best_d:
            best_d, best = d, p

    target = best
    if target is None and op is not None:
        target = op
    if target is None:
        for x, y in ((0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)):
            if w > 0 and h > 0 and (x, y) != s:
                target = (x, y)
                break
    if target is None:
        return [0, 0]

    dx = 0 if target[0] == sx else (1 if target[0] > sx else -1)
    dy = 0 if target[1] == sy else (1 if target[1] > sy else -1)

    blocked = set()
    for b in obs:
        p = pos(b)
        if p is not None:
            blocked.add(p)

    cand = [(dx, dy), (dx, 0), (0, dy), (dx, -dy), (-dx, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
    for mx, my in cand:
        nx, ny = sx + mx, sy + my
        if w and (nx < 0 or nx >= w):
            continue
        if h and (ny < 0 or ny >= h):
            continue
        if (nx, ny) in blocked:
            continue
        return [mx, my]
    return [0, 0]

